@file:OptIn(KtGramInternal::class)

package eu.vendeli.tgbot.mock

import eu.vendeli.tgbot.TelegramBot
import eu.vendeli.tgbot.annotations.internal.KtGramInternal
import eu.vendeli.tgbot.interfaces.helper.ContextLoader
import eu.vendeli.tgbot.utils.common.CtxUtils

private object NoClassData : CtxUtils {
    override val isClassDataInitialized: Lazy<Unit> = lazy { }

    override suspend fun clearClassData(tgId: Long) = Unit
}

/** The library requires a context loader, normally generated by KSP; tests here use the functional DSL only. */
class NoopContextLoader : ContextLoader {
    override fun load(bot: TelegramBot) {
        bot.update.____ctxUtils = NoClassData
    }
}
